# Run from a temp copy, so the git pull in stage 1 can't rewrite this file
# while bash is still reading it.
if [[ -z "${WIZARD_REPO:-}" ]]; then
  WIZARD_REPO=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)
  _self=$(mktemp "${TMPDIR:-/tmp}/guardrails-hand-tests.XXXXXX")
  cp "${BASH_SOURCE[0]}" "$_self"
  WIZARD_REPO="$WIZARD_REPO" exec bash "$_self" "$@"
fi

