# Results, not secrets: one KEY=value line per check. Re-runs offer the saved
# answer as the default, so you can stop and pick up later.
mkdir -p "$HOME/.claude/state"
ENV_FILE="$HOME/.claude/state/guardrails-hand-tests.results"

RESULT_KEYS=()
RESULT_LABELS=()

# result KEY "label" records pass, fail or skip, then an optional note.
result() {
  local key="$1" label="$2" v n
  RESULT_KEYS+=("$key")
  RESULT_LABELS+=("$label")
  while :; do
    ask "$key" "Result: $label [pass/fail/skip]"
    v="${!key}"
    case "$v" in
      pass|p) v=pass; break ;;
      fail|f) v=fail; break ;;
      skip|s) v=skip; break ;;
    esac
    warn "type pass, fail or skip"
  done
  write_env "$key" "$v"
  ask "${key}_NOTE" "Note (what you saw, one line; Enter for none):"
  n="${key}_NOTE"
  write_env "${key}_NOTE" "${!n}"
}

# prompt_block "text" shows a prompt to paste into a Claude session.
prompt_block() {
  printf '\n  %s┌ paste into the session%s\n' "$DIM" "$RESET"
  printf '%s\n' "$1" | fold -s -w 74 | while IFS= read -r line; do printf '  %s│%s %s\n' "$DIM" "$RESET" "$line"; done
  printf '  %s└%s\n\n' "$DIM" "$RESET"
}

