  if git -C "$REPO" ls-remote --exit-code --heads origin "$b" >/dev/null 2>&1; then
    if confirm "Delete origin/$b?"; then
      git -C "$REPO" push -q origin --delete "$b"
      say "${GREEN}✓${RESET} deleted origin/$b"
    else
      SKIPPED+=("delete origin/$b")
    fi
  else
    note "origin/$b doesn't exist, nothing to delete"
  fi
done
git -C "$REPO" worktree remove --force "$CLOUD_WT" 2>/dev/null || true
git -C "$REPO" worktree prune
git -C "$REPO" branch -D "$CLOUD_BRANCH" >/dev/null 2>&1 || true
if [[ -d "$SCRATCH" ]] && confirm "Delete the scratch repo $SCRATCH?"; then
  rm -rf "$SCRATCH"
fi
[[ -f "${BACKUP:-}" ]] && note "Your old settings stay at $BACKUP; delete it once you're happy."
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Post the results to #32"
COMMENT=$(mktemp "${TMPDIR:-/tmp}/guardrails-hand-tests-comment.XXXXXX")
{
  printf 'Hand-test results for #32, recorded %s.\n\n' "$(date +%Y-%m-%d)"
  printf '| Check | Result | Note |\n|---|---|---|\n'
  i=0
  while (( i < ${#RESULT_KEYS[@]} )); do
    k="${RESULT_KEYS[$i]}"
    n="${k}_NOTE"
    note_text="${!n:-}"
    printf '| %s | %s | %s |\n' "${RESULT_LABELS[$i]}" "${!k}" "${note_text//|/\\|}"
    i=$((i + 1))
  done
  printf '\nA fail on the git fetch or push check means `git fetch` and `git push` go into `sandbox.excludedCommands`, merged between sessions.\n'
  printf '\n_Recorded with `docs/plans/guardrails-hand-tests.sh`._\n'
} > "$COMMENT"
sed 's/^/    /' "$COMMENT"
printf '\n'
if confirm "Post this as a comment on #32?"; then
  if command -v gh >/dev/null 2>&1 && gh issue comment 32 --repo "$GH_REPO" --body-file "$COMMENT" >/dev/null; then
    say "${GREEN}✓${RESET} posted to https://github.com/$GH_REPO/issues/32"
  else
    SKIPPED+=("post the results: gh issue comment 32 --repo $GH_REPO --body-file $COMMENT")
  fi
else
  SKIPPED+=("post the results: gh issue comment 32 --repo $GH_REPO --body-file $COMMENT")
fi
note "Results are also saved in $ENV_FILE."
pause

finish
